Definition FFIELD_STACK : Z := 192.   (* [comment removed for export] *)

Definition ffield_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (res Fa : Z) (f : nat) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' r,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (res, res + 8)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' res [C8 (wz r)]
    /\ FieldsC m' Fa S L ns ls em /\ FT m'
    /\ ((r = Fa + 32 /\ ~ has_eqv key_lt (key_of em) (zbytes (ft_nameb f)) S)
        \/ (exists d, em !! r = Some d /\ r ∈ L /\ ieq (zbytes (ft_nameb f)) (zbytes (el_name d)) = true)).

Definition ffield_stmt : Prop := forall (res Fa : Z) (f : nat) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo : Z) (rj : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  FieldsC m Fa S L ns ls em -> FT m -> (1 <= f < 130)%nat ->
  rw_cells usegs m res [CB 8 rj] -> bv_unsigned sp <= res -> res + 8 <= Fa ->
  stk usegs m lo (bv_unsigned sp) -> lo + FFIELD_STACK <= bv_unsigned sp -> hceil <= lo -> bv_unsigned sp <= Fa ->
  bv_unsigned sp mod 16 = 0 ->                                                  (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (ffield_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc res Fa f S L ns ls em lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) (wz Fa) (wz (Z.of_nat f)) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FIELDS_FIND_F) fc None m (seg_rom usegs)).
