Lemma ValCells_value_bytes : forall m v d, rw_cells usegs m v (ValCells d) ->
  bytes_at usegs m (v + 10 + zlength (el_name d)) (el_value d).
Proof.
  intros m v d H.
  pose proof H as [[WF _] _]. cbn in WF. destruct WF as (_ & _ & _ & LP & _).
  pose proof (rw_cells_bytes_at _ _ _ _ H) as B. unfold ValCells in B.
  cbn [cells_bytes cbytes] in B.
  apply bytes_at_app in B. destruct B as [_ B]. rewrite length_le2 in B.
  apply bytes_at_app in B. destruct B as [_ B]. rewrite length_le2 in B.
  apply bytes_at_app in B. destruct B as [_ B]. rewrite length_le2 in B.
  apply bytes_at_app in B. destruct B as [_ B]. rewrite LP in B.
  apply bytes_at_app in B. destruct B as [_ B].
  apply bytes_at_app in B. destruct B as [_ B]. cbn [length] in B.
  apply bytes_at_app in B. destruct B as [B _].
  unfold zlength. replace (v + 10 + Z.of_nat (length (el_name d))) with
    (v + Z.of_nat 2 + Z.of_nat 2 + Z.of_nat 2 + Z.of_nat 2 + Z.of_nat (length (el_name d)) + Z.of_nat 2) by lia. exact B.
Qed.

Definition FINDEX_STACK : Z := 224.   (* [comment removed for export] *)

Definition findex_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fa : Z) (f : nat) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' vp vbs,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz vp) (wz (zlength vbs)) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ FieldsC m' Fa S L ns ls em /\ FT m'
    /\ bytes_at usegs m' vp vbs
    /\ ((vp = 0 /\ vbs = [] /\ ~ has_eqv key_lt (key_of em) (zbytes (ft_nameb f)) S)
        \/ (exists r d, em !! r = Some d /\ r ∈ L /\ ieq (zbytes (ft_nameb f)) (zbytes (el_name d)) = true
                        /\ vbs = el_value d /\ vp = r + 58 + zlength (el_name d) /\ 0 < r /\ r + esize d <= hceil)).

