Lemma otf_epi : forall (lo : Z) rax (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (s0' s1' s2' s3' s4' s5' w1 w2 w3 w4 : word) (j8 : list byte) (F : bvmap 5 word) fc (m : mem),
  rw_cells usegs m (bv_unsigned sp + -96) [CB 8 j8; C8 w1; C8 w2; C8 w3; C8 w4; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  stk usegs m lo (bv_unsigned sp + -96) -> lo + 96 <= bv_unsigned sp -> 0 <= lo -> mem_inv usegs m ->
  evt usegs (fun ms' => ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                F (ret_pc ra) fc None m (seg_rom usegs)
                       /\ stk usegs m lo (bv_unsigned sp))
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2 s0' s1' a0 a1 a2 a3 a4 a5 a6 a7 s2' s3' s4' s5' s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_OTF_RET) fc None m (seg_rom usegs)).
