  Definition otf_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (P f ecA : Z) (name value : list byte) (E0 : ecv)
      (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (LB' : list block) (E' : ecv)
                    S' L' ns' ls' em',
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' LB' m'
      /\ FieldsC m' (P + 80) S' L' ns' ls' em' /\ FieldsOwn LB' em' /\ FT m'
      /\ rw_cells usegs m' ecA (ErrCodeCells E')
      /\ xpres LB (bv_unsigned sp) ((ecA, ecA + 24) :: (P + 80, P + 128) :: elemsW L) m m'
      /\ ( (* [comment removed for export] *)
           (s' = s /\ LB' = LB /\ E' = E0 /\ S' = S /\ L' = L /\ ns' = ns /\ ls' = ls /\ em' = em)
           (* [comment removed for export] *)
        \/ (exists (p : bptr) (A : Z) pad tl,
              E' = EC_clear /\ rblock_range A (elem_block_size name (trim value))
              /\ LB' = (p, A, elem_block_size name (trim value)) :: LB
              /\ em' = <[A := mkElt f name (trim value) pad tl]> em /\ (A + 16) ∈ S' /\ A ∈ L') ).

  Definition otf_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (P f np vp ecA : Z) (mb : byte) (name value : list byte) (E0 : ecv)
           (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo B : Z) (errv : word),
      a0 = Z_to_bv 64 P -> a1 = Z_to_bv 64 f -> a2 = Z_to_bv 64 np -> a3 = Z_to_bv 64 (zlength name) ->
      a4 = Z_to_bv 64 vp -> a5 = Z_to_bv 64 (zlength value) -> a6 = Z_to_bv 64 ecA ->
      FieldsC m (P + 80) S L ns ls em -> FieldsOwn LB em -> FT m -> rw_cells usegs m (P + 242) [C1 mb] ->
      bytes_at usegs m np name -> rclient_range LB (bv_unsigned sp) np (zlength name) -> np + zlength name < 2^64 ->
      bytes_at usegs m vp value -> rclient_range LB (bv_unsigned sp) vp (zlength value) -> vp + zlength value < 2^64 ->
      zlength name <= 65533 -> zlength value <= 65533 -> 0 <= f < 2^16 ->
      rw_cells usegs m ecA (ErrCodeCells E0) -> bv_unsigned sp <= ecA -> ecA + 24 <= B ->
      (ecA + 24 <= P + 80 \/ P + 128 <= ecA) -> (np + zlength name <= ecA \/ ecA + 24 <= np) -> (vp + zlength value <= ecA \/ ecA + 24 <= vp) ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + (zlength name + zlength value + 67) <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B -> P + 243 <= B -> B <= 2^64 ->
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - OTF_STACK -> bv_unsigned sp <= P ->
      rw_cells usegs m (errno_addr tp) [C4 errv] -> mem_inv usegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned sp mod 16 = 0 -> bv_unsigned mb <= 1 ->                      (* [comment removed for export] *)
      hs_SR H (otf_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB P f ecA name value E0 S L ns ls em lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_ON_TRAILER_FIELD_IMPL) fc None m (seg_rom usegs)) mo).
